using System.Buffers.Binary;

namespace KeepClip.App.Clipboard;

internal static class CopySoundWave
{
    public static byte[] WithVolume(byte[] source, int volume)
    {
        // The bundled chime is a canonical PCM16 mono WAV generated by Generate-CopySound.ps1.
        if (source.Length < 44 || !source.AsSpan(0, 4).SequenceEqual("RIFF"u8) || !source.AsSpan(8, 8).SequenceEqual("WAVEfmt "u8) || BinaryPrimitives.ReadInt32LittleEndian(source.AsSpan(16)) != 16 || BinaryPrimitives.ReadInt16LittleEndian(source.AsSpan(20)) != 1 || BinaryPrimitives.ReadInt16LittleEndian(source.AsSpan(22)) != 1 || BinaryPrimitives.ReadInt16LittleEndian(source.AsSpan(32)) != 2 || BinaryPrimitives.ReadInt16LittleEndian(source.AsSpan(34)) != 16 || !source.AsSpan(36, 4).SequenceEqual("data"u8) || BinaryPrimitives.ReadInt32LittleEndian(source.AsSpan(40)) != source.Length - 44 || (source.Length - 44) % 2 != 0)
        {
            throw new InvalidDataException("Unsupported copy chime format.");
        }

        var result = (byte[])source.Clone();
        var gain = Math.Clamp(volume, 0, 100) / 50.0;
        for (var offset = 44; offset < result.Length; offset += 2)
        {
            var sample = BinaryPrimitives.ReadInt16LittleEndian(source.AsSpan(offset));
            var scaled = (short)Math.Clamp(Math.Round(sample * gain), short.MinValue, short.MaxValue);
            BinaryPrimitives.WriteInt16LittleEndian(result.AsSpan(offset), scaled);
        }

        return result;
    }
}
